void UDragonsGI_C::CheckGameAccess(bool* IsClear) const
{
	static class UFunction* Func = nullptr;

	if (Func == nullptr)
		Func = Class->GetFunction("DragonsGI_C", "CheckGameAccess");

	Params::DragonsGI_C_CheckGameAccess Parms{};

	UObject::ProcessEvent(Func, &Parms);

	if (IsClear != nullptr)
		*IsClear = Parms.IsClear;
}


